    // New: Selected voices section with edit/remove
    @ViewBuilder
    private func selectedVoicesSection() -> some View {
        if selectedProfiles.isEmpty {
            Text("Tap Add voice... to choose voices and tune pitch/volume.")
                .foregroundStyle(.secondary)
                .padding(.vertical, 8)
        } else {
            ChorusLabSelectedVoicesSection(
                profiles: $selectedProfiles,
                lastDurationByID: $lastDurationByID,
                isCalibrating: isCalibrating,
                calibratingVoiceID: calibratingVoiceID,
                isPlaying: isPlaying,
                resolveName: { id in resolvedName(for: id) },
                timingCellWidth: Metrics.Layout.timingCellWidth,
                onEdit: { index in
                    presentEditVoice(index: index)
                },
                onSync: { voiceID in
                    guard let idx = selectedProfiles.firstIndex(where: { $0.id == voiceID }) else { return }
                    // Route row-level sync through the shared calibrationTask so the
                    // global Stop button can cancel it.
                    calibrationTask?.cancel()
                    calibrationTask = Task { @MainActor in
                        if isCalibrating || isPlaying { return }
                        isCalibrating = true
                        calibratingVoiceID = voiceID
                        let prevScale = rateScale
                        rateScale = 1.0
                        let io = engineFactory()
                        defer {
                            isCalibrating = false
                            calibratingVoiceID = nil
                            rateScale = prevScale
                            baseProfiles = selectedProfiles
                            selectedProfiles = ChorusMath.applyAdjustments(
                                baseProfiles: baseProfiles,
                                rateScale: rateScale,
                                pitchOffset: pitchOffset
                            )
                            calibrationTask = nil
                        }
                        await Task.yield()
                        io.setVoiceProfile(selectedProfiles[idx])
                        let result = await VoiceTempoCalibrator.fitRate(
                            io: io,
                            voiceID: voiceID,
                            phrase: customText,
                            targetSeconds: targetSeconds,
                            tolerance: Metrics.Calibration.tolerance,
                            maxIterations: Metrics.Calibration.maxIterations,
                            onIteration: { _, measured, _ in
                                lastDurationByID[voiceID] = measured
                                lastChorusSeconds = measured
                            }
                        )
                        if Task.isCancelled { return }
                        selectedProfiles[idx].rate = result.finalRate
                        lastDurationByID[voiceID] = result.measured
                        lastChorusSeconds = result.measured
                    }
                },
                onDelete: { removedID in
                    if let idx = selectedProfiles.firstIndex(where: { $0.id == removedID }) {
                        selectedProfiles.remove(at: idx)
                    }
                    lastDurationByID.removeValue(forKey: removedID)
                    baseProfiles = selectedProfiles
                    selectedProfiles = ChorusMath.applyAdjustments(
                        baseProfiles: baseProfiles,
                        rateScale: rateScale,
                        pitchOffset: pitchOffset
                    )
                }
            )
        }
    }

    // MARK: - Calibration and tuning

    /// Synchronize all selected voice rates to match the target duration.
    /// Runs rate calibration in parallel for each voice, updates baseProfiles and selectedProfiles with fitted rates.
    /// The global rateScale is temporarily normalized to 1.0 during calibration to avoid interaction effects;
    /// it is restored afterward.
    /// Any in-flight calibration is cancelled before starting a new one.
    private func synchronizeRates() {
        guard !selectedProfiles.isEmpty else { return }
        isCalibrating = true
        calibratingVoiceID = nil // "Sync all" does not highlight a single row
        let phrase = customText
        let prevScale = rateScale
        // Cancel any in-flight calibration task
        calibrationTask?.cancel()
        calibrationTask = Task { @MainActor in
            defer {
                isCalibrating = false
                calibrationTask = nil
                // After calibration, refresh selectedProfiles from baseline with current global sliders
                // First, restore the user's speed scale and ensure baseline reflects any calibrated rate changes:
                rateScale = prevScale
                baseProfiles = selectedProfiles
                // Apply global scaling/offset to produce effective profiles:
                selectedProfiles = ChorusMath.applyAdjustments(
                    baseProfiles: baseProfiles,
                    rateScale: rateScale,
                    pitchOffset: pitchOffset
                )
            }
            // Normalize global speed during calibration to avoid compounding while fitting
            rateScale = 1.0

            // Snapshot current profiles so parallel tasks have stable inputs/indexes.
            let snapshots = selectedProfiles.enumerated().map { ($0.offset, $0.element) }

            await withTaskGroup(of: (Int, String, Double, Double)?.self) { group in
                for (index, profile) in snapshots {
                    let voiceID = profile.id
                    group.addTask { [phrase, targetSeconds] in
                        if Task.isCancelled { return nil }
                        let io = await MainActor.run { self.engineFactory() }
                        await io.setVoiceProfile(profile)

                        let result = await VoiceTempoCalibrator.fitRate(
                            io: io,
                            voiceID: voiceID,
                            phrase: phrase,
                            targetSeconds: targetSeconds,
                            tolerance: Metrics.Calibration.tolerance,
                            maxIterations: Metrics.Calibration.maxIterations,
                            onIteration: { _, measured, _ in
                                // Hop back to the main actor from the calibrator’s
                                // worker context without making onIteration itself async.
                                Task { @MainActor in
                                    self.lastDurationByID[voiceID] = measured
                                    self.lastChorusSeconds = measured
                                }
                            }
                        )

                        if Task.isCancelled { return nil }
                        return (index, voiceID, result.finalRate, result.measured)
                    }
                }

                for await outcome in group {
                    guard let (index, voiceID, finalRate, measured) = outcome else { continue }
                    if Task.isCancelled { continue }
                    // Apply results on the main actor; this function is already
                    // @MainActor, but be explicit to satisfy Swift 6 isolation.
                    await MainActor.run {
                        if self.selectedProfiles.indices.contains(index) {
                            self.selectedProfiles[index].rate = finalRate
                        }
                        self.lastDurationByID[voiceID] = measured
                        self.lastChorusSeconds = measured
                    }
                }
            }
        }
    }

    @ViewBuilder
    private func actionButtonsRow() -> some View {
        ChorusLabActionRowView(
            isPlaying: $isPlaying,
            isCalibrating: $isCalibrating,
            hasSelection: !selectedProfiles.isEmpty,
            onPlay: {
                // Inline to avoid calling a mutating helper from an immutable context
                Task { @MainActor in
                    isPlaying = true
                    let t0 = Date()
                    await chorus.speak(customText, withVoiceProfiles: selectedProfiles)
                    let elapsed = Date().timeIntervalSince(t0)
                    lastChorusSeconds = elapsed
                    isPlaying = false
                }
            },
            onStop: {
                // Inline immediate stop logic
                calibrationTask?.cancel()
                calibrationTask = nil
                isCalibrating = false
                chorus.stop()
                if isPlaying { isPlaying = false }
            },
            onSync: { synchronizeRates() }
        )
        .padding(.bottom, Metrics.Padding.headerV)
    }

    @ViewBuilder
    private func globalAdjustmentsSection() -> some View {
        ChorusLabGlobalAdjustmentsView(
            rateScale: $rateScale,
            pitchOffset: $pitchOffset,
            speedRange: Metrics.Adjustments.speedRange,
            pitchOffsetRange: Metrics.Adjustments.pitchOffsetRange,
            sliderStep: Metrics.Controls.sliderStep,
            onChange: {
                // Pure transform: re-derive effective profiles from baseline + sliders
                selectedProfiles = ChorusMath.applyAdjustments(
                    baseProfiles: baseProfiles,
                    rateScale: rateScale,
                    pitchOffset: pitchOffset
                )
            }
        )
    }

    // Extracted views are now in Components as internal types:
    // - ChorusLabActionRowView
    // - ChorusLabGlobalAdjustmentsView
    // - ChorusLabSelectedVoiceRow

    // Synchronize a single voice (row-level). Runs a focused calibration for that index.
    // (moved: synchronizeVoice -> ChorusLabView+Logic.swift)

    // (moved: startChorus -> ChorusLabView+Logic.swift)

    // Cancel any in-flight calibration and stop the chorus immediately.
    // (moved: stopAll -> ChorusLabView+Logic.swift)

    /// Retrieve all available system voices, sorted alphabetically by name.
    /// Used to populate the voice selection menu and seed initial voices.
    func availableVoices() -> [TTSVoiceInfo] {
        voicesProvider.all()
            .sorted { $0.name.localizedCaseInsensitiveCompare($1.name) == .orderedAscending }
    }

    /// Populate the chorus with random voices from the user's preferred language.
    /// Each voice gets a slight pitch offset for tonal differentiation. Establishes baseProfiles and selectedProfiles.
    /// Called once on first appearance if the chorus is empty, to provide an immediate playable setup.
    /// - Parameter count: Number of random voices to select (default: 2).
    private func seedInitialVoices(count: Int = 2) {
        // Filter to current language base code (e.g., "en").
        let baseLang: String = {
            let tag = Locale.preferredLanguages.first ?? Locale.current.identifier
            if let dash = tag.firstIndex(of: "-") { return String(tag[..<dash]).lowercased() }
            return tag.lowercased()
        }()
        let list = availableVoices().filter {
            let lang = $0.language
            let code: String = {
                if let dash = lang.firstIndex(of: "-") { return String(lang[..<dash]).lowercased() }
                return lang.lowercased()
            }()
            return code == baseLang
        }
        guard !list.isEmpty else { return }

        // Random without replacement
        let slice = Array(list.shuffled().prefix(max(0, count)))
        var picks: [TTSVoiceProfile] = []
        let pitchOffsets: [Float] = [-0.05, 0.05, 0.1, -0.1]

        for (index, voice) in slice.enumerated() {
            var profile = TTSVoiceProfile(id: voice.id, rate: Metrics.Defaults.rate, pitch: Metrics.Defaults.pitch, volume: Metrics.Defaults.volume)
            if index < pitchOffsets.count {
                profile.pitch = (profile.pitch + pitchOffsets[index]).clamped(to: Metrics.Pitch.clampLo...Metrics.Pitch.clampHi)
            }
            picks.append(profile)
        }
        // Establish baseline and effective selections
        baseProfiles = picks
        selectedProfiles = picks
    }

    // MARK: - Tuner integration

    /// Show the voice tuner sheet to add a new voice to the chorus.
    /// Seeds the tuner with a random voice from the user's preferred language, or any voice if none match.
    /// VoiceChooserView allows full profile adjustment (pitch, volume, rate) and preview playback.
    private func presentAddVoice() {
        editingIndex = nil
        // Use the injected engine factory for testability and consistency.
        tunerEngine = engineFactory()
        // Prefer a random voice from the user's preferred language; fall back to any.
        let baseLang: String = {
            let tag = Locale.preferredLanguages.first ?? Locale.current.identifier
            if let dash = tag.firstIndex(of: "-") { return String(tag[..<dash]).lowercased() }
            return tag.lowercased()
        }()
        let sameLang = availableVoices().filter {
            let lang = $0.language
            let code: String = {
                if let dash = lang.firstIndex(of: "-") { return String(lang[..<dash]).lowercased() }
                return lang.lowercased()
            }()
            return code == baseLang
        }
        let pool = sameLang.isEmpty ? availableVoices() : sameLang
        if let pick = pool.randomElement() {
            tunerSelection = pick.id
            let seed = TTSVoiceProfile(
                id: pick.id,
                rate: Metrics.Defaults.rate,
                pitch: Metrics.Defaults.pitch,
                volume: Metrics.Defaults.volume
            )
            tunerEngine.setVoiceProfile(seed)
            tunerEngine.setDefaultVoiceProfile(seed)
        } else {
            tunerSelection = nil
        }
        showTuner = true
    }

    /// Show the voice tuner sheet to edit an existing voice in the chorus.
    /// Pre-populates the tuner with the current profile so the user sees their adjustments.
    /// - Parameter index: Index in selectedProfiles of the voice to edit.
    private func presentEditVoice(index: Int) {
        guard selectedProfiles.indices.contains(index) else { return }
        editingIndex = index
        tunerEngine = engineFactory()
        let prof = selectedProfiles[index]
        tunerEngine.setVoiceProfile(prof)
        tunerEngine.setDefaultVoiceProfile(prof)
        tunerSelection = prof.id
        showTuner = true
    }

    /// Apply the result of voice tuning (from VoiceChooserView) back to the chorus.
    /// If editingIndex is set, updates the voice in place. Otherwise, appends a new voice.
    /// Resyncs baseProfiles and reapplies global adjustments to ensure consistency.
    private func applyTunerSelection() {
        guard let id = tunerSelection else { return }
        // Prefer the specific profile returned by the tuner engine; fall back to its default;
        // finally, seed a mid profile if neither is available yet.
        var tuned: TTSVoiceProfile? = tunerEngine.getVoiceProfile(id: id)
        if tuned == nil, let def = tunerEngine.getDefaultVoiceProfile() {
            tuned = TTSVoiceProfile(id: id, rate: def.rate, pitch: def.pitch, volume: def.volume)
        }
        if tuned == nil {
            tuned = TTSVoiceProfile(id: id, rate: Metrics.Defaults.rate, pitch: Metrics.Defaults.pitch, volume: Metrics.Defaults.volume)
        }
        guard let tuned else { return }
        if let idx = editingIndex, selectedProfiles.indices.contains(idx) {
            // Editing an existing row updates only that row
            selectedProfiles[idx] = tuned
        } else {
            // Always allow duplicates when adding
            selectedProfiles.append(tuned)
        }
        // Clear edit state
        editingIndex = nil
        tunerSelection = nil
        // Keep baseline aligned to effective list, then re-apply globals
        baseProfiles = selectedProfiles
        // Re-apply global adjustments so effective profiles reflect sliders
        selectedProfiles = ChorusMath.applyAdjustments(
            baseProfiles: baseProfiles,
            rateScale: rateScale,
            pitchOffset: pitchOffset
        )
    }
}

// MARK: - Code generation

/// Generate a Swift code snippet that recreates the current chorus setup.
/// Users can copy this snippet and paste it into their app to reproduce the exact voice profiles and phrase.
/// - Parameters:
///   - phrase: The text to speak in the generated snippet (default: placeholder).
///   - profiles: The voice profiles to serialize.
/// - Returns: Formatted Swift code snippet (multi-line string) ready to paste.
internal func makeChorusSnippet(_ phrase: String = "Your phrase", for profiles: [TTSVoiceProfile]) -> String {
    guard !profiles.isEmpty else { return "" }

    let body = profiles.map { "    " + $0.initStr }
        .joined(separator: ",\n")
    return """
    // VoiceKit chorus setup example
    import VoiceKit

    let chorusProfiles = [
    \(body)
    ]
    // Use with VoiceChorus:
    await VoiceChorus().speak("\(phrase)", withVoiceProfiles: chorusProfiles)
    """
}

